-- The schema ZestSSH 2.3.0 (and 2.2.1) makes: user_version 40.
CREATE TABLE "automation_history" ("id" TEXT NOT NULL, "timestamp" INTEGER NOT NULL, "action" TEXT NOT NULL, "connection_id" TEXT NOT NULL, "command" TEXT NOT NULL, "snippet_name" TEXT NULL, "stdout" TEXT NOT NULL DEFAULT '', "stderr" TEXT NOT NULL DEFAULT '', "exit_code" INTEGER NULL, "success" INTEGER NOT NULL CHECK ("success" IN (0, 1)), "elapsed_ms" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "command_history" ("id" TEXT NOT NULL, "command" TEXT NOT NULL, "connection_id" TEXT NULL, "host_label" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NULL, "exit_code" INTEGER NULL, "duration_ms" INTEGER NULL, "cwd" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "connection_groups" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "is_expanded" INTEGER NOT NULL DEFAULT 1 CHECK ("is_expanded" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NULL, "color_index" INTEGER NULL, "color_value" INTEGER NULL, "icon_code_point" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "connection_tags" ("connection_id" TEXT NOT NULL, "tag" TEXT NOT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("connection_id", "tag"));
CREATE TABLE "connections" ("id" TEXT NOT NULL, "label" TEXT NOT NULL, "host" TEXT NOT NULL, "port" INTEGER NOT NULL DEFAULT 22, "identity_id" TEXT NULL REFERENCES identities (id), "group_id" TEXT NULL REFERENCES connection_groups (id), "color_index" INTEGER NOT NULL DEFAULT 0, "color_value" INTEGER NULL, "protocol" TEXT NOT NULL DEFAULT 'ssh', "zlib_compression" INTEGER NOT NULL DEFAULT 0 CHECK ("zlib_compression" IN (0, 1)), "startup_command" TEXT NULL, "snippet_id" TEXT NULL REFERENCES snippets (id), "connect_via_id" TEXT NULL, "keep_alive_seconds" INTEGER NOT NULL DEFAULT 0, "wol_mac_address" TEXT NULL, "wol_broadcast_address" TEXT NULL DEFAULT '255.255.255.255', "wol_port" INTEGER NULL DEFAULT 9, "env_vars" TEXT NOT NULL DEFAULT '', "forward_agent" INTEGER NOT NULL DEFAULT 0 CHECK ("forward_agent" IN (0, 1)), "compatibility_mode" INTEGER NOT NULL DEFAULT 0 CHECK ("compatibility_mode" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "size_tier" INTEGER NOT NULL DEFAULT 1, "icon_id" TEXT NULL, "custom_icon" TEXT NULL, "pinned" INTEGER NOT NULL DEFAULT 0 CHECK ("pinned" IN (0, 1)), "note" TEXT NULL, "monitored" INTEGER NOT NULL DEFAULT 0 CHECK ("monitored" IN (0, 1)), "pins" TEXT NULL, "last_remote_path" TEXT NULL, "last_remote_user" TEXT NULL, "last_remote_path_at" INTEGER NULL, "last_connected" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "feedback_queue" ("nonce" TEXT NOT NULL, "payload" TEXT NOT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("nonce"));
CREATE TABLE "host_network_overrides" ("id" TEXT NOT NULL, "connection_id" TEXT NOT NULL, "network_id" TEXT NOT NULL, "address" TEXT NULL, "port" INTEGER NULL, "username" TEXT NULL, "identity_id" TEXT NULL, "jump_host_id" TEXT NULL, "jump_chain_json" TEXT NULL, "skip_host" INTEGER NULL CHECK ("skip_host" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "identities" ("id" TEXT NOT NULL, "label" TEXT NOT NULL, "username" TEXT NOT NULL, "auth_method" TEXT NOT NULL, "key_type" TEXT NULL, "public_key_fingerprint" TEXT NULL, "public_key_data" TEXT NULL, "cert_serial" TEXT NULL, "cert_key_id" TEXT NULL, "cert_principals" TEXT NULL, "cert_ca_fingerprint" TEXT NULL, "cert_valid_before" INTEGER NULL, "cert_valid_after" INTEGER NULL, "agent_socket_path" TEXT NULL, "uses_agent" INTEGER NOT NULL DEFAULT 0 CHECK ("uses_agent" IN (0, 1)), "color_index" INTEGER NOT NULL DEFAULT 0, "color_value" INTEGER NULL, "is_default" INTEGER NOT NULL DEFAULT 0 CHECK ("is_default" IN (0, 1)), "allow_unattended" INTEGER NOT NULL DEFAULT 0 CHECK ("allow_unattended" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "known_hosts" ("id" TEXT NOT NULL, "host" TEXT NOT NULL, "port" INTEGER NOT NULL, "key_type" TEXT NOT NULL, "fingerprint" TEXT NOT NULL, "public_key_base64" TEXT NOT NULL, "first_seen" INTEGER NOT NULL, "last_seen" INTEGER NOT NULL, "recorded_device" TEXT NULL, "locally_verified" INTEGER NOT NULL DEFAULT 1 CHECK ("locally_verified" IN (0, 1)), "via_scope" TEXT NULL, PRIMARY KEY ("id"), UNIQUE ("host", "port", "key_type", "via_scope"));
CREATE TABLE "local_state" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "monitor_samples" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "connection_id" TEXT NOT NULL, "captured_at" INTEGER NOT NULL, "ok" INTEGER NOT NULL DEFAULT 1 CHECK ("ok" IN (0, 1)), "resolution_seconds" INTEGER NOT NULL DEFAULT 0, "cpu_percent" REAL NULL, "ram_percent" REAL NULL, "swap_percent" REAL NULL, "disk_percent" REAL NULL, "load1" REAL NULL, "load5" REAL NULL, "load15" REAL NULL, "temp_c" REAL NULL, "ping_ms" INTEGER NULL);
CREATE TABLE "networks" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "color_index" INTEGER NOT NULL DEFAULT 0, "color_value" INTEGER NULL, "icon_code_point" INTEGER NOT NULL, "icon_font_family" TEXT NULL, "icon_font_package" TEXT NULL, "triggers_json" TEXT NOT NULL DEFAULT '[]', "is_fallback" INTEGER NOT NULL DEFAULT 0 CHECK ("is_fallback" IN (0, 1)), "bring_up_vpn" TEXT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "port_forward_network_overrides" ("id" TEXT NOT NULL, "rule_id" TEXT NOT NULL, "network_id" TEXT NOT NULL, "state" TEXT NOT NULL DEFAULT 'inherit', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("rule_id", "network_id"));
CREATE TABLE "port_forward_rules" ("id" TEXT NOT NULL, "connection_id" TEXT NOT NULL REFERENCES connections (id), "type" TEXT NOT NULL, "bind_address" TEXT NOT NULL DEFAULT '127.0.0.1', "bind_port" INTEGER NOT NULL, "remote_host" TEXT NOT NULL, "remote_port" INTEGER NOT NULL, "auto_start" INTEGER NOT NULL DEFAULT 0 CHECK ("auto_start" IN (0, 1)), "reconnect" INTEGER NOT NULL DEFAULT 1 CHECK ("reconnect" IN (0, 1)), "exit_on_failure" INTEGER NOT NULL DEFAULT 1 CHECK ("exit_on_failure" IN (0, 1)), "gateway_ports" INTEGER NOT NULL DEFAULT 0 CHECK ("gateway_ports" IN (0, 1)), "ssh_flags" TEXT NULL, "label" TEXT NULL, "network_id" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "scheduled_tasks" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "action" TEXT NOT NULL, "connection_id" TEXT NOT NULL, "command" TEXT NULL, "snippet_name" TEXT NULL, "workflow_id" TEXT NULL, "schedule_type" TEXT NOT NULL, "interval_minutes" INTEGER NOT NULL DEFAULT 60, "hour" INTEGER NULL, "minute" INTEGER NULL, "day_of_week" INTEGER NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "api_key_id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "last_run_at" INTEGER NULL, "last_result" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "sftp_sync_manifest" ("host_id" TEXT NOT NULL, "remote_root" TEXT NOT NULL, "rel_path" TEXT NOT NULL, "local_size" INTEGER NOT NULL, "local_mtime_s" INTEGER NOT NULL, "content_hash" TEXT NULL, "uploaded_at" INTEGER NOT NULL, PRIMARY KEY ("host_id", "remote_root", "rel_path"));
CREATE TABLE "snippet_categories" ("name" TEXT NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "color_index" INTEGER NULL, "color_value" INTEGER NULL, "hidden" INTEGER NOT NULL DEFAULT 0 CHECK ("hidden" IN (0, 1)), "updated_at" INTEGER NULL, PRIMARY KEY ("name"));
CREATE TABLE "snippets" ("id" TEXT NOT NULL, "label" TEXT NOT NULL, "command" TEXT NOT NULL, "category" TEXT NULL, "confirm_before_run" INTEGER NOT NULL DEFAULT 0 CHECK ("confirm_before_run" IN (0, 1)), "is_default" INTEGER NOT NULL DEFAULT 0 CHECK ("is_default" IN (0, 1)), "metadata" TEXT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "terminal_triggers" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "pattern" TEXT NOT NULL, "case_sensitive" INTEGER NOT NULL DEFAULT 0 CHECK ("case_sensitive" IN (0, 1)), "notify" INTEGER NOT NULL DEFAULT 1 CHECK ("notify" IN (0, 1)), "highlight" INTEGER NOT NULL DEFAULT 0 CHECK ("highlight" IN (0, 1)), "highlight_color" INTEGER NULL, "play_sound" INTEGER NOT NULL DEFAULT 0 CHECK ("play_sound" IN (0, 1)), "connection_id" TEXT NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "tombstones" ("entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "deleted_at" INTEGER NOT NULL, PRIMARY KEY ("entity_type", "entity_id"));
CREATE TABLE "workflows" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NULL, "steps_json" TEXT NOT NULL DEFAULT '[]', "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "notify_on_failure" INTEGER NOT NULL DEFAULT 1 CHECK ("notify_on_failure" IN (0, 1)), "notify_on_success" INTEGER NOT NULL DEFAULT 0 CHECK ("notify_on_success" IN (0, 1)), "created_at" INTEGER NOT NULL, "last_run_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_connection_tags_conn ON connection_tags (connection_id);
CREATE INDEX idx_connection_tags_tag ON connection_tags (tag);
CREATE INDEX idx_connections_host ON connections (host);
CREATE INDEX idx_connections_label ON connections (label);
CREATE INDEX idx_host_net_overrides_conn ON host_network_overrides (connection_id);
CREATE INDEX idx_host_net_overrides_net ON host_network_overrides (network_id);
CREATE INDEX idx_known_hosts_host ON known_hosts (host);
CREATE INDEX idx_monitor_samples_conn_time ON monitor_samples (connection_id, captured_at);
CREATE INDEX idx_monitor_samples_time ON monitor_samples (captured_at);
CREATE INDEX idx_pf_net_overrides_net ON port_forward_network_overrides (network_id);
CREATE INDEX idx_pf_net_overrides_rule ON port_forward_network_overrides (rule_id);
CREATE TRIGGER trg_command_history_ua_ins AFTER INSERT ON command_history WHEN NEW.updated_at IS NULL BEGIN UPDATE command_history SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_command_history_ua_upd AFTER UPDATE ON command_history WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE command_history SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_connection_groups_ua_ins AFTER INSERT ON connection_groups WHEN NEW.updated_at IS NULL BEGIN UPDATE connection_groups SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_connection_groups_ua_upd AFTER UPDATE ON connection_groups WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE connection_groups SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_identities_ua_ins AFTER INSERT ON identities WHEN NEW.updated_at IS NULL BEGIN UPDATE identities SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_identities_ua_upd AFTER UPDATE ON identities WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE identities SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_networks_ua_ins AFTER INSERT ON networks WHEN NEW.updated_at IS NULL BEGIN UPDATE networks SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_networks_ua_upd AFTER UPDATE ON networks WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE networks SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_port_forward_rules_ua_ins AFTER INSERT ON port_forward_rules WHEN NEW.updated_at IS NULL BEGIN UPDATE port_forward_rules SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_port_forward_rules_ua_upd AFTER UPDATE ON port_forward_rules WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE port_forward_rules SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_snippet_categories_ua_ins AFTER INSERT ON snippet_categories WHEN NEW.updated_at IS NULL BEGIN UPDATE snippet_categories SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE name = NEW.name; END;
CREATE TRIGGER trg_snippet_categories_ua_upd AFTER UPDATE ON snippet_categories WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE snippet_categories SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE name = NEW.name; END;
CREATE TRIGGER trg_terminal_triggers_ua_ins AFTER INSERT ON terminal_triggers WHEN NEW.updated_at IS NULL BEGIN UPDATE terminal_triggers SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_terminal_triggers_ua_upd AFTER UPDATE ON terminal_triggers WHEN NEW.updated_at IS OLD.updated_at BEGIN UPDATE terminal_triggers SET updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = NEW.id; END;
